describe('pickSessionToken', () => {
  it('accepts both conventional spellings', () => {
    expect(pickSessionToken({ access_token: 'a' }, 'access')).toBe('a');
    expect(pickSessionToken({ accessToken: 'a' }, 'access')).toBe('a');
    expect(pickSessionToken({ refresh_token: 'r' }, 'refresh')).toBe('r');
    expect(pickSessionToken({ refreshToken: 'r' }, 'refresh')).toBe('r');
  });
  it('refuses a non-object, a missing field and an empty string', () => {
    expect(pickSessionToken(null, 'access')).toBeUndefined();
    expect(pickSessionToken('a string', 'access')).toBeUndefined();
    expect(pickSessionToken({}, 'access')).toBeUndefined();
    expect(pickSessionToken({ access_token: '' }, 'access')).toBeUndefined();
    expect(pickSessionToken({ access_token: 42 }, 'access')).toBeUndefined();
  });
  it('does not read an access token as a refresh token', () => {
    expect(pickSessionToken({ access_token: 'a' }, 'refresh')).toBeUndefined();
  });
});

describe('session lifecycle', () => {
  afterEach(async () => { await clearSession(); });
  it('starts signed out', () => {
    expect(getAccessToken()).toBeNull();
    expect(isSignedIn()).toBe(false);
  });
  it('signs in, exposes the token, and signs out again', async () => {
    await setSession('access-1', 'refresh-1');
    expect(getAccessToken()).toBe('access-1');
    expect(isSignedIn()).toBe(true);
    await clearSession();
    expect(getAccessToken()).toBeNull();
    expect(isSignedIn()).toBe(false);
  });
  it('notifies subscribers on both transitions, and stops after unsubscribe', async () => {
    const seen: boolean[] = [];
    const off = onSessionChange((v) => seen.push(v));
    await setSession('a');
    await clearSession();
    off();
    await setSession('b');
    expect(seen).toEqual([true, false]);
  });
  it('remembers a refresh token in memory for passcode sealing', () => {
    const { provideRefreshToken, peekRefreshToken } = sessionModule;
    if (!provideRefreshToken || !peekRefreshToken) return; // no vault in this build
    provideRefreshToken('r-mem');
    expect(peekRefreshToken()).toBe('r-mem');
  });
  it('reports whether anything is stored, and resumes only when it is', async () => {
    await clearSession();
    expect(await hasStoredSession()).toBe(false);
    expect(await tryResumeSession()).toBe(false);
    await setSession('a', 'r');
    expect(await hasStoredSession()).toBe(true);
  });
  it('loadSession is safe to call with nothing stored', async () => {
    await clearSession();
    await expect(loadSession()).resolves.toBeUndefined();
  });
});

/**
 * These run against BOTH refresh implementations, so every case here has to
 * hold for both.
 *
 * The first one used to be "fails when no refresh endpoint is wired", which is
 * only true of the hook build: an app with a wired refresh operation HAS an
 * endpoint, so clearing the hook fell through to the generated call, reached
 * for the network, and hung. And because refreshSession is single-flight, the
 * promise that never settled was then handed to every later caller — one wrong
 * test timed the whole describe out, four times thirty seconds, and the CI
 * pipeline aborts before the scan stage when the suite fails.
 *
 * The branch-independent version of the same assertion is the earlier exit both
 * builds share: with no refresh token stored there is nothing to exchange, and
 * neither implementation reaches its transport.
 */
describe('refreshSession', () => {
  afterEach(async () => { setRefreshHook(null); await clearSession(); });
  it('fails with nothing to exchange when no refresh token is stored', async () => {
    await clearSession();
    expect(await refreshSession()).toBe(false);
  });
  it('adopts the new access token when the hook succeeds', async () => {
    await setSession('old', 'r');
    setRefreshHook(async () => 'new-access');
    expect(await refreshSession()).toBe(true);
    expect(getAccessToken()).toBe('new-access');
  });
  it('fails when the hook declines, and leaves the old token alone', async () => {
    await setSession('old', 'r');
    setRefreshHook(async () => null);
    expect(await refreshSession()).toBe(false);
  });
  it('shares ONE in-flight refresh between concurrent callers', async () => {
    await setSession('old', 'r');
    let calls = 0;
    setRefreshHook(async () => { calls += 1; return 'new'; });
    const [a, b, c] = await Promise.all([refreshSession(), refreshSession(), refreshSession()]);
    expect([a, b, c]).toEqual([true, true, true]);
    expect(calls).toBe(1);
  });
});

describe('appState', () => {
  it('stores and reads a value, and is undefined for an unset key', () => {
    setAppValue('otpPhone', '+971500000000');
    expect(getAppValue('otpPhone')).toBe('+971500000000');
    expect(getAppValue('never-set')).toBeUndefined();
  });
});

describe('formStore', () => {
  it('is app-level: a value written for one key is readable afterwards', () => {
    useFormStore.getState().setValues((s) => ({ ...s, 'w:1': 'typed' }));
    expect(useFormStore.getState().values['w:1']).toBe('typed');
  });
});

describe('permissions', () => {
  it('classifies a state for the caller', () => {
    expect(isUsable('granted')).toBe(true);
    expect(isUsable('limited')).toBe(true);
    expect(isUsable('blocked')).toBe(false);
    expect(needsSettings('blocked')).toBe(true);
    expect(needsSettings('undetermined')).toBe(false);
  });
  // The two libraries disagree on the vocabulary, which is the whole reason the
  // normaliser exists: expo's 'denied' means "will not ask again" (blocked),
  // while react-native-permissions' DENIED means "not asked yet".
  it.each(true
    ? [['granted', 'granted'], ['undetermined', 'undetermined'], ['denied', 'blocked']]
    : [
        ['granted', 'granted'],
        ['denied', 'undetermined'],
        ['blocked', 'blocked'],
        ['limited', 'limited'],
        ['unavailable', 'unavailable'],
        ['something else entirely', 'denied'],
      ])('maps the native status %s to %s, for every permission', async (status, expected) => {
    (globalThis as any).__permStatus = status;
    for (const name of ['camera', 'location', 'notifications'] as const) {
      expect(await request(name)).toBe(expected);
      expect(await check(name)).toBe(expected);
    }
  });
});
